                sr,sc=r,c
    # flood-fill same nonzero object, starting at nonzero neighbors of marker
    stack=[]; seen=set()
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        rr,cc=sr+dr,sc+dc
        if 0<=rr<h and 0<=cc<w and grid[rr][cc]!=0:
            stack.append((rr,cc))
    while stack:
