        if (r,c) in seen or not (0<=r<h and 0<=c<w) or grid[r][c]==0 or grid[r][c]==5: continue
        seen.add((r,c))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            stack.append((r+dr,c+dc))
    minr=min(r for r,c in seen); maxr=max(r for r,c in seen)
    minc=min(c for r,c in seen); maxc=max(c for r,c in seen)
    return [[grid[r][c] if (r,c) in seen else 0 for c in range(minc,maxc+1)] for r in range(minr,maxr+1)]"}

